targets.rawSql:
select collected_at as "time", 'User sessions - inst ' || inst_id as metric, user_sessions::double precision as value
from oracle_instance_samples
where $__timeFilter(collected_at) and source_database = ${source_database:sqlstring}
union all
select collected_at as "time", 'Active user - inst ' || inst_id as metric, active_user_sessions::double precision as value
from oracle_instance_samples
where $__timeFilter(collected_at) and source_database = ${source_database:sqlstring}
union all
select collected_at as "time", 'Processes - inst ' || inst_id as metric, process_count::double precision as value
from oracle_instance_samples
where $__timeFilter(collected_at) and source_database = ${source_database:sqlstring}
order by 1;
